package vn.covie.inventory.application;
import java.util.UUID; import org.springframework.stereotype.Service; import vn.covie.inventory.api.dto.*; import vn.covie.shared.idempotency.IdempotencyExecutor; import vn.covie.shared.web.*;
@Service public class InventoryBulkItemExecutor{private final IdempotencyExecutor idempotency;private final InventoryAdjustmentService adjustments;public InventoryBulkItemExecutor(IdempotencyExecutor idempotency,InventoryAdjustmentService adjustments){this.idempotency=idempotency;this.adjustments=adjustments;}public InventoryBulkItemResult execute(UUID actor,UUID merchantId,BulkSetStockItem item,String reason,String note,String batchKey){var command=new BulkSetStockItemCommand(merchantId,item.locationVariantId(),item.stockOnHand(),reason,note);return idempotency.execute(actor,"INVENTORY_BULK_SET_STOCK_ITEM",batchKey+":"+item.locationVariantId(),command,200,InventoryBulkItemResult.class,()->{try{var result=adjustments.setStockInternal(actor,command.merchantId(),command.locationVariantId(),command.stockOnHand(),command.reasonCode(),command.note());return InventoryBulkItemResult.success(command.locationVariantId(),result.stockOnHand());}catch(ApiException ex){if(ex.code()!=ErrorCode.INVENTORY_BELOW_RESERVED_QUANTITY&&ex.code()!=ErrorCode.INVENTORY_NOT_TRACKED&&ex.code()!=ErrorCode.MERCHANT_ACTION_NOT_ALLOWED)throw ex;return InventoryBulkItemResult.failure(command.locationVariantId(),ex.code().name());}});}}
record BulkSetStockItemCommand(UUID merchantId,UUID locationVariantId,long stockOnHand,String reasonCode,String note){}
